import {ACCESSORIES,MUZZLES} from './equipment.mjs';
import {waveKind} from './campaign.mjs';
import {MATERIALS,RECIPES,ELEMENTS,MAX_LEVEL,ABILITIES,DROP_RATES,ENEMY_TYPES,waveScaling} from './catalog.mjs';
import {Run,gunStats} from './model.mjs';
import {Renderer} from './render.mjs';
const $=id=>document.getElementById(id);
export const run=new Run();
const renderer=new Renderer($('arena'));
let keys={},joy={x:0,y:0},pointer=null,last=0,phase='',inventorySignature='',selected='water',pending=null,dialogType=null,resumeAfterLog=false,previousFocus=null,sound=false,audio,toastUntil=0,equipmentSignature='',sidebarTab='equipment';
const gunIds=Object.keys(RECIPES);
const startId=id=>'start'+id[0].toUpperCase()+id.slice(1);
const currentGun=()=>run.state==='menu'?{type:run.startingGun,level:1}:run.lab.gun;
const gunName=()=>{const gun=currentGun();return gun.type==='normal'?'普通枪':RECIPES[gun.type].name};
const stockText=stock=>Object.entries(stock).filter(([,n])=>n>0).map(([id,n])=>`${MATERIALS[id].formula} ×${n}`).join(' · ')||'无';
function beep(hz,seconds=.06,type='sine',volume=.018){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume?.();const o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.value=hz;v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+seconds);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+seconds)}catch{}}
function clearInput(){keys={};joy={x:0,y:0};pointer=null;$('stick').style.transform='translate(0,0)'}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');toastUntil=performance.now()+2100}
function start(){setSidebarTab('equipment');clearInput();closeDialog(false);run.start();phase='';inventorySignature='';last=performance.now();sync();$('arena').focus({preventScroll:true});beep(330,.12)}
function pause(){if(dialogType)return;if(run.state==='playing'){run.state='paused';clearInput()}else if(run.state==='paused'){run.state='playing';last=performance.now()}sync()}
function menu(){setSidebarTab('equipment');clearInput();run.reset();phase='';sync()}
function syncBag(){const enabled=run.state==='lab';const sig=JSON.stringify([run.lab.inventory,enabled]);if(sig===inventorySignature)return;inventorySignature=sig;$('materialCards').innerHTML=Object.entries(MATERIALS).map(([id,m])=>`<button class="material-card" data-add="${id}" draggable="${enabled&&(run.lab.inventory[id]??0)>0}" style="--material:${m.color}" aria-label="${enabled?'向炉内加入':'背包'}${m.name}，当前${run.lab.inventory[id]??0}份" ${!enabled||!run.lab.inventory[id]?'disabled':''}><span class="material-icon">${m.formula}</span><span class="material-copy"><b>${m.name}</b><small>${m.label}${enabled?' · 点击投料':''}</small></span><span class="material-count"><small>×</small>${run.lab.inventory[id]??0}</span></button>`).join('');$('inventoryTotal').textContent=`${Object.values(run.lab.inventory).reduce((a,b)=>a+b,0)} 份`;$('bagHint').textContent=enabled?'拖到炉内或点击投料；炉内物质点击可取回。':'击败怪物，靠近拾取。波末自动回收。'}
function syncGun(){const gun=currentGun(),s=run.state==='menu'?gunStats(gun,run.abilities):run.stats,recipe=RECIPES[gun.type];$('gunName').textContent=gunName();$('gunLevel').textContent=gun.type==='normal'?'基础型 / LV. 0':`${recipe.family} / LV. ${gun.level}`;$('gunIcon').style.color=recipe?.color||'#a9bda0';$('statDamage').textContent=Number(s.damage.toFixed(1));$('statRange').textContent=s.range;$('statRate').textContent=`${(1/s.interval).toFixed(1)}/s`;$('statEffectLabel').textContent='枪型效果';$('statBurn').textContent=gun.type==='flame'?`灼烧 ${s.burnDps??0}/s`:gun.type==='acid'?`腐蚀 ${Math.round((s.corrosionStrength??0)*100)}%/层`:gun.type==='gas'?`击退 ${s.knockback??'—'}`:gun.type==='electric'?`连锁 ${s.chainCount??'—'}`:gun.type==='iron'?`贯穿 ${s.pierce??'—'}`:'直线水柱';$('gunDescription').textContent=recipe?recipe.effect:'一把可靠的普通枪。先活下来，再想办法变强。'}

function statText(value,unit){return unit==='%'?`${Math.round(value*100)}%`:unit==='×'?`${value.toFixed(2)}×`:`${Number(value.toFixed(1))}${unit}`}
function syncCharacter(){const a=run.abilities;$('abilityStats').innerHTML=`<div class="section-label">角色能力 <span>LV.${run.level} · ◇${run.diamonds}</span></div><div class="character-grid"><span>最大生命 <b>${a.maxHp}</b></span><span>防御减伤 <b>${Math.round(a.defense*100)}%</b></span><span>移动速度 <b>${a.speed}</b></span><span>拾取范围 <b>${a.magnet}</b></span><span>生命恢复 <b>${a.regen}/s</b></span><span>暴击率 <b>${Math.round(a.crit*100)}%</b></span></div><small>角色能力本局保留，换枪不清零。</small>`}
function chooseAbility(id){if(dialogType||!run.chooseAbility(id))return;phase='';clearInput();sync();beep(700,.15)}
function toggleDropMode(){if(run.setDropMode(run.dropMode==='standard'?'high':'standard')){phase='';sync()}}

function setSidebarTab(tab){sidebarTab=tab;for(const [key,pane,button] of [['equipment','equipmentPane','sidebarEquipment'],['bag','backpack','sidebarBag'],['recipes','recipesPane','sidebarRecipes']]){const active=key===tab;$(pane).classList.toggle('hidden',!active);$(button).setAttribute('aria-selected',String(active));$(button).setAttribute('tabindex',active?'0':'-1')}}
function browseRecipe(direction){if(run.state!=='lab'||dialogType)return;selected=gunIds[(gunIds.indexOf(selected)+direction+gunIds.length)%gunIds.length];syncLab()}
$('prevRecipe').onclick=()=>browseRecipe(-1);$('nextRecipe').onclick=()=>browseRecipe(1);$('sidebarEquipment').onclick=()=>setSidebarTab('equipment');$('sidebarBag').onclick=()=>setSidebarTab('bag');$('sidebarRecipes').onclick=()=>setSidebarTab('recipes');
const sidebarKeys=['equipment','bag','recipes'];for(const [index,id] of ['sidebarEquipment','sidebarBag','sidebarRecipes'].entries())$(id).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const next=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;setSidebarTab(sidebarKeys[next]);$( ['sidebarEquipment','sidebarBag','sidebarRecipes'][next]).focus()});
function syncRecipes(){const isLab=run.state==='lab';$('recipeCount').textContent=`${String(gunIds.length).padStart(2,'0')} AVAILABLE`;$('recipeCards').innerHTML=Object.entries(RECIPES).map(([id,r])=>{const affordable=Object.entries(r.cost).every(([k,n])=>(run.lab.inventory[k]??0)+(run.lab.furnace[k]??0)>=n);return `<button class="recipe-card ${id===selected?'selected':''}" data-recipe="${id}" ${!isLab?'disabled':''}><div class="recipe-head"><b>${r.name}</b><span class="${id==='flame'?'flame-tag':''}">${r.tag}</span></div><p>${stockText(r.cost)}</p><small>${isLab?(affordable?'材料充足 · 点击选择':'材料不足 · 仍可查看配方'):'波间实验室可改装'}</small></button>`}).join('')}
function syncLab(){const at=gunIds.indexOf(selected);$('recipePosition').textContent=`${at+1} / ${gunIds.length}`;$('recipeSelection').textContent=selected===run.lab.gun.type?'当前持枪 · 优先增强':'浏览其他枪 · 制作后才替换';syncBag();syncGun();syncRecipes();const l=run.lab,r=RECIPES[selected],info=l.recipeInfo(selected);$('furnaceContents').innerHTML=Object.entries(l.furnace).filter(([,n])=>n>0).map(([id,n])=>`<button class="furnace-chip" data-remove="${id}" draggable="true" aria-label="取回一份${MATERIALS[id].name}">${MATERIALS[id].formula} ×${n}<span>−</span></button>`).join('')||'<span class="empty-furnace">可直接制作，也可拖入物质。</span>';$('recipeKind').textContent=r.tag;$('recipeTitle').textContent=r.name;$('recipeNumber').textContent=r.displayFormula;$('equation').textContent=r.equation||r.assemblyText;$('scienceNote').textContent=r.fact+(selected==='flame'?' 产水进入实验收集瓶，不回流可用背包。':'');$('furnaceSymbol').textContent=r.displayFormula;$('reactorLevel').textContent=l.gun.type===selected?l.gun.level+1:1;$('ignition').checked=l.ignition;$('ignition').disabled=selected!=='flame';const missing=stockText(info.missing);$('requirements').classList.toggle('missing',!info.ready||selected==='flame'&&!l.ignition);$('requirements').textContent=!info.ready?`材料还缺：${missing}`:selected==='flame'&&!l.ignition?'需要开启炉内点火源':'材料充足 · 点击制作自动扣除，拖拽可选';$('craft').disabled=!info.ready||selected==='flame'&&!l.ignition;$('craft').innerHTML=`${l.gun.type===selected?'同系增强':info.replace?'替换为':'制作'}${r.name}${l.gun.type===selected?` · Lv.${l.gun.level+1}`:''} <span>↗</span>`;$('nextWave').disabled=l.gun.type==='normal';$('nextWave').innerHTML=l.gun.type==='normal'?'先完成一次改装，再进入下一关 <span>→</span>':`装备就绪，开始第 ${run.wave+1} 关 <span>→</span>`;$('returnAll').disabled=Object.values(l.furnace).every(n=>n===0);$('supplyNote').classList.remove('hidden');$('supplyNote').textContent=Object.values(run.supply).some(n=>n>0)?`首波教学补给：${stockText(run.supply)}。场上物质已自动回收。`:'场上物质已自动回收，库存已足够改装。';$('scienceTip').textContent=r.fact;if(info.maxed){$('craft').disabled=true;$('craft').textContent=`已达本原型上限 · Lv.${MAX_LEVEL}`;$('requirements').textContent='本系已满级，不再消耗材料；可退回材料或改选另一系。';$('requirements').classList.remove('missing');$('reactorLevel').textContent=MAX_LEVEL}}
function move(id,to){if(run.state!=='lab'||dialogType)return;if(run.lab.moveMaterial(id,to)){syncLab();beep(to==='furnace'?460:300,.04)}}
function requestCraft(){if(run.state!=='lab'||dialogType)return;let result=run.craft(selected);if(result.reason==='replace'){pending=selected;showDialog('replace',`<div class="eyebrow">RECONFIGURE / 异系替换</div><h2>换一个方向，重新开始。</h2><p>当前 <strong>${gunName()} Lv.${run.lab.gun.level}</strong> 将被替换为 <strong>${RECIPES[pending].name} Lv.1</strong>。旧系强化清零，材料不返还。</p><p>确认后才会自动扣除配方材料；取消会保留所有材料。</p><button class="primary" id="confirmReplace">确认替换并清零 <span>→</span></button><button class="cancel" id="cancelDialog">保留当前装备</button>`);$('confirmReplace').onclick=()=>{const id=pending;closeDialog(false);completeCraft(run.craft(id,true),id)};$('cancelDialog').onclick=()=>closeDialog();return}completeCraft(result,selected)}
function completeCraft(result,id){if(!result.ok){$('labFeedback').textContent='条件尚未满足，请检查材料数量和点火源。';return}beep(660,.16);const r=RECIPES[id];$('labFeedback').textContent=`${r.name} Lv.${run.lab.gun.level} 已就绪。${id==='flame'?'反应产水 2 份已记入收集瓶。':''}剩余材料已退回背包。`;syncLab()}
function showDialog(type,html){previousFocus=document.activeElement;dialogType=type;$('dialogCard').innerHTML=html;$('dialogOverlay').classList.remove('hidden');$('dialogCard').querySelector('button')?.focus({preventScroll:true})}
function closeDialog(restore=true){$('dialogOverlay').classList.add('hidden');if(dialogType==='log'&&resumeAfterLog){run.state='playing';last=performance.now()}resumeAfterLog=false;dialogType=null;pending=null;if(restore)previousFocus?.focus?.({preventScroll:true});sync()}
function openLog(){if(dialogType)return;resumeAfterLog=run.state==='playing';if(resumeAfterLog){run.state='paused';clearInput();sync()}showDialog('log',`<div class="eyebrow">DISCOVERY LOG / 本局图鉴</div><h2>把发现，留在这里。</h2><div class="log-entry"><h3>元素与组成</h3><p>${Object.entries(ELEMENTS).map(([symbol,name])=>`${symbol} · ${name}`).join('　')}</p><p>元素符号描述组成；HCl(aq)表示盐酸中的溶质，NaCl表示离子组成比，电弧能量由枪械电源提供。</p></div>${Object.entries(MATERIALS).map(([id,m])=>`<div class="log-entry"><h3>${m.formula} · ${m.name}</h3><p>${m.fact}</p></div>`).join('')}<div class="log-entry"><h3>本局已制作</h3><p>${run.lab.discoveries.length?run.lab.discoveries.map(id=>RECIPES[id].name).join('、'):'尚未完成改装；第一波结束后进入实验室。'}</p></div>${run.lab.discoveries.includes('flame')?`<div class="log-entry"><h3>氢气燃烧 · 已发现</h3><p class="formula">2H₂ + O₂ → 2H₂O</p><p>条件：点火。氧气是氧化剂，空气中也存在氧气。试验产水累计 ${run.lab.products.water} 份，仅作收集记录。</p></div>`:''}<div class="log-entry"><h3>失控实验样本</h3>${ENEMY_TYPES.map(e=>`<p><strong>${e.name}</strong> · ${e.description} · ◇${e.diamonds}</p>`).join('')}<p>这些是化学概念的虚构拟人化；掉落为回收实验物资，不代表怪物死亡的真实化学反应。</p></div><div class="log-entry"><h3>化学事实与游戏效果</h3><p>水柱、灼烧、腐蚀增伤、气压击退、电弧连锁、铁弹贯穿与不限弹药均属于游戏机制；不代表物质的全部现实性质或实际实验操作。隐藏配方后续加入。</p></div><button class="cancel" id="cancelDialog">返回${resumeAfterLog?'战斗':'实验'}</button>`);$('cancelDialog').onclick=()=>closeDialog()}
function syncEquipment(){const gun=currentGun().type,sig=JSON.stringify([gun,run.attachments,run.muzzle]);if(sig!==equipmentSignature){equipmentSignature=sig;$('equipmentSlots').innerHTML=[0,1].map(i=>{const id=run.attachments[i],a=ACCESSORIES[id];return `<div class="gear-slot"><b>配件 ${i+1} · ${a?a.name:'空槽'}</b><small>${a?(a.gun===gun?'生效 · '+a.description:'未生效 · 需要'+RECIPES[a.gun].name):'精英怪掉落三选一'}</small><small id="gearCharge${i}"></small>${a?`<details><summary>化学与原理</summary>${a.science}</details>`:''}</div>`}).join('')+`<div class="gear-slot"><b>枪口 · ${run.muzzle?MUZZLES[run.muzzle].name:'空槽'}</b><small>${run.muzzle?MUZZLES[run.muzzle].description:'第9关 Boss 掉落 · 所有枪通用'}</small></div>`}run.attachments.forEach((id,i)=>{$('gearCharge'+i).textContent=ACCESSORIES[id].gun!==gun?'未生效':id==='rail'?'被动加速已启用':id==='condenser'?`储水 ${Math.floor(run.condenser.charge*100)}%`:`积蓄 ${Math.min(100,Math.floor((run.accessoryCharge[id]||0)*100))}%`})}
function renderReward(card){const muzzle=run.rewardKind==='muzzle',catalog=muzzle?MUZZLES:ACCESSORIES;card.innerHTML=`<div class="eyebrow">${muzzle?'BOSS LOOT / 枪口':'ELITE LOOT / 配件'}</div><h2>收下新的<span>可能。</span></h2><p>${muzzle?'枪口通用，装上即改变主枪攻击形态。':'最多同时装两个配件，主枪适配才生效。'}</p><div class="ability-options">${run.rewardChoices.map((id,i)=>{const a=catalog[id];return `<button class="ability-option" id="reward${i}"><strong>${a.name}</strong><p>${a.description}</p><small>${muzzle?'所有枪通用':a.gun===run.lab.gun.type?'当前主枪适配':'需要'+RECIPES[a.gun].name+' · 当前不生效'}</small></button>`}).join('')}</div><button id="skipReward" class="back-link">放弃本次奖励，继续战斗</button>`;run.rewardChoices.forEach((id,i)=>{$('reward'+i).onclick=()=>selectReward(id)});$('skipReward').onclick=()=>{run.chooseReward(null);phase='';sync()}}
function selectReward(id){if(run.state!=='reward')return;if(run.rewardKind==='accessory'&&run.attachments.length>=2){showDialog('replacement',`<h2>替换哪个配件？</h2><p>新配件：${ACCESSORIES[id].name}</p>${run.attachments.map((old,i)=>`<button id="replaceSlot${i}" class="cancel">替换 ${ACCESSORIES[old].name}</button>`).join('')}<button id="cancelRewardSwap" class="back-link">返回三选一</button>`);run.attachments.forEach((old,i)=>{$('replaceSlot'+i).onclick=()=>{closeDialog(false);run.chooseReward(id,i);phase='';sync()}});$('cancelRewardSwap').onclick=()=>closeDialog();return}run.chooseReward(id);phase='';sync()}
function openEquipmentTest(){showDialog('test',`<h2>装备试验</h2><p>测试入口：直接进入指定关卡，奖励与敌人规则照常。</p><label>关卡 <select id="testWave">${Array.from({length:10},(_,i)=>`<option value="${i+1}">第${i+1}关</option>`).join('')}</select></label>${[0,1].map(i=>`<label>配件${i+1} <select id="testAccessory${i}"><option value="">空槽</option>${Object.entries(ACCESSORIES).map(([id,a])=>`<option value="${id}">${a.name}（${RECIPES[a.gun].name}）</option>`).join('')}</select></label>`).join('')}<label>枪口 <select id="testMuzzle"><option value="">原版枪口</option>${Object.entries(MUZZLES).map(([id,a])=>`<option value="${id}">${a.name}</option>`).join('')}</select></label><button id="launchTest" class="primary">携带当前选中的主枪，进入测试</button><button id="closeTest" class="back-link">取消</button>`);$('launchTest').onclick=()=>{const wave=Number($('testWave').value)||1,slots=[...new Set([$('testAccessory0').value,$('testAccessory1').value].filter(id=>ACCESSORIES[id]))],muzzle=$('testMuzzle').value;start();run.wave=Math.max(1,Math.min(10,wave));run.attachments=slots;run.muzzle=MUZZLES[muzzle]?muzzle:null;phase='';sync()};$('closeTest').onclick=()=>closeDialog()}
function syncCondenser(){const p=run.condenser; $('condenserPanel').classList.toggle('hidden',!run.legacy&&!run.attachments.includes('condenser'));const flame=currentGun().type==='flame';$('condenserPercent').textContent=Math.floor(p.charge*100)+'%';$('condenserFill').style.width=p.charge*100+'%';$('condenserStatus').textContent=!flame?'选择氢燃烧枪，体验喷火蓄水配件。':!p.equipped?'水包已拆下，主枪保持原样。':p.spraying?(p.collecting?'正在喷水 · 喷火同时补水':'正在喷水 · 停火只耗水'):p.collecting?'喷火 → 冷凝收集 · 满包自动侧后方喷水':p.charge>0?'等待主枪开火补水 · 蓄满才启动':'空水包已装好 · 喷火时自动蓄水';$('toggleCondenser').textContent=p.equipped?'拆下水包（试玩）':'装上空水包（试玩）';$('toggleCondenser').disabled=!run.legacy||!flame||!['playing','paused','lab'].includes(run.state);$('toggleCondenser').setAttribute('aria-pressed',String(p.equipped))}
function sync(){const state=run.state,lab=state==='lab';syncCondenser();syncEquipment();$('hpText').textContent=`${Math.ceil(run.hp)} / ${run.abilities.maxHp}`;$('hpBar').style.width=`${run.hp/run.abilities.maxHp*100}%`;$('kills').textContent=run.kills;$('waveLabel').textContent=String(run.wave).padStart(2,'0');const t=Math.max(0,Math.ceil(run.duration-run.waveTime));$('timer').textContent=lab?'LAB':run.waveTime>=run.duration&&!run.specialDefeated&&waveKind(run.wave)!=='normal'?'BOSS':`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('phaseLabel').textContent=({menu:'准备实验',playing:run.wave===1?'收集阶段':'改装验证',lab:'波间实验室',paused:'实验暂停',upgrade:'角色能力升级',reward:'精英 / Boss 战利品',dead:'实验中止',won:'实验完成'})[state];$('phaseDot').style.background=lab?'#77d9f5':state==='dead'?'#ed8e92':'#b9e4ad';$('pause').disabled=!['playing','paused'].includes(state);$('pause').textContent=state==='paused'?'▷':'Ⅱ';$('pause').setAttribute('aria-label',state==='paused'?'继续游戏':'暂停游戏');$('playerLevel').textContent=`角色 LV.${run.level}`;$('experienceText').textContent=`${run.xp} / ${run.needed} ◇`;$('experienceBar').style.width=`${Math.min(100,run.xp/run.needed*100)}%`;$('experienceHud').classList.toggle('hidden',lab);syncBag();if(phase===state)return;phase=state;clearInput();$('labView').classList.toggle('hidden',!lab);$('stage').classList.toggle('lab-stage',lab);$('battleHud').classList.toggle('hidden',lab);$('controlsNote').classList.toggle('hidden',lab);$('screenOverlay').classList.toggle('hidden',!['menu','paused','upgrade','reward','dead','won'].includes(state));$('fieldHint').textContent=lab?'材料不会凭空消失：制作只消耗配方所需，多余退回。':`第${run.wave}关 · 怪物血量 ×${(1+(run.wave-1)*.13).toFixed(2)} / 伤害 ×${(1+(run.wave-1)*.09).toFixed(2)} · ${waveKind(run.wave)==='elite'?'击败精英获得配件':run.wave>=9?'击败Boss，注意预警':'收集物质，结束后进入实验室'}`;syncGun();syncCharacter();syncRecipes();if(lab){selected=Object.hasOwn(RECIPES,run.lab.gun.type)?run.lab.gun.type:gunIds[0];setSidebarTab('bag');$('labFeedback').textContent='选择配方后可直接制作；拖拽投料是可选操作。';syncLab();$('furnace').focus({preventScroll:true});return}if(state==='playing'){$('supplyNote').classList.add('hidden');return}const card=$('screenCard');if(state==='reward'){renderReward(card)}else if(state==='upgrade'){card.innerHTML=`<div class="eyebrow">DIAMOND UPGRADE / 角色 LV.${run.level+1}</div><h2>进化的是你，<span>不止是枪。</span></h2><p>钻石积累了经验。选择一项能力，换枪后仍然保留。</p><div class="ability-options">${run.upgradeChoices.map((id,i)=>{const d=ABILITIES[id],before=run.abilities[d.stat],after=Math.min(d.max??Infinity,before+d.step);return `<button class="ability-option" id="ability${i}"><span>${d.icon}</span><strong>${d.name}</strong><p>${d.description}</p><b>${statText(before,d.unit)} → ${statText(after,d.unit)}</b><small>按 ${i+1} 选择</small></button>`}).join('')}</div>`;run.upgradeChoices.forEach((id,i)=>{$(`ability${i}`).onclick=()=>chooseAbility(id)})}else if(state==='menu'){
 card.innerHTML=`<div class="eyebrow">PLAYTEST / 免费选择初始化学枪</div><h2>选一把<span>化学枪。</span></h2><p>免费装配 Lv.1，立即测试喷射效果与射程。</p><div class="starting-guns">${gunIds.map((id,i)=>{const r=RECIPES[id],stats=gunStats({type:id,level:1});return `<button id="${startId(id)}" data-start-gun="${id}" class="starting-gun ${run.startingGun===id?'selected':''}" aria-pressed="${run.startingGun===id}"><span style="color:${r.color}">${r.icon}</span><strong>${r.name}</strong><small>${r.summary}</small><b>射程 ${stats.range} · ${r.family}</b><em>按 ${i+1} 选择 · 免费 Lv.1</em></button>`}).join('')}</div><button id="start" class="primary">携带${RECIPES[run.startingGun].name}出发 <span>↗</span></button><div class="start-tip">Enter 开始 · 十关战斗 · 精英配件 / Boss枪口</div><button class="drop-setting" id="dropMode">物质掉率：${run.dropMode==='high'?'试玩加量 75%':'标准 18%'} · 点击切换</button><div class="start-tip">第3/5/7关精英掉配件，第9关Boss掉枪口。</div><button class="back-link" id="equipmentTest">装备试验 · 直接选配件、枪口与关卡</button>`;
 gunIds.forEach(id=>{$(startId(id)).onclick=()=>{run.selectStartingGun(id);phase='';sync()}});$('equipmentTest').onclick=openEquipmentTest;$('start').onclick=start;$('dropMode').onclick=toggleDropMode
}else if(state==='paused'){card.innerHTML='<div class="eyebrow">EXPERIMENT PAUSED</div><h2>暂停一下，<br>思路<span>继续。</span></h2><p>实验现场已暂停，准备好后继续。</p><button id="resume" class="primary">继续实验 <span>▷</span></button><button id="back" class="back-link">返回主菜单</button>';$('resume').onclick=pause;$('back').onclick=menu}else if(['dead','won'].includes(state)){const won=state==='won';card.innerHTML=`<div class="eyebrow">${won?'EXPERIMENT COMPLETE':'TRY ANOTHER HYPOTHESIS'}</div><h2>${won?'你的配方，<br><span>经得起考验。</span>':'这次倒下，<br><span>下次换个配方。</span>'}</h2><div class="result-stats"><div><b>${Math.round(run.elapsed)}s</b><small>生存时间</small></div><div><b>${run.kills}</b><small>清除目标</small></div><div><b>${Math.round(run.damageDone)}</b><small>总伤害</small></div></div><div class="result-gun">${gunName()} Lv.${run.lab.gun.level} · ${run.lab.gun.type==='flame'?`灼烧伤害 ${Math.round(run.burnDamage)}`:`射速 ${(1/run.stats.interval).toFixed(1)}/s`}</div><p>${won?'下一次，试试另一种化学选择。':'物质与强化在重开时重置，重新验证你的选择。'}</p><button id="restart" class="primary">再做一次实验 <span>↻</span></button><button id="back" class="back-link">返回主菜单</button>`;$('restart').onclick=start;$('back').onclick=menu}card.querySelector('button')?.focus({preventScroll:true})}
$('toggleCondenser').onclick=()=>{if(!['playing','paused','lab'].includes(run.state)||run.lab.gun.type!=='flame')return;run.condenser.toggle();syncCondenser()};
$('materialCards').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)move(b.dataset.add,'furnace')});$('furnaceContents').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)move(b.dataset.remove,'inventory')});$('recipeCards').addEventListener('click',e=>{const b=e.target.closest('[data-recipe]');if(b&&run.state==='lab'&&!dialogType){selected=b.dataset.recipe;syncLab()}});
$('returnAll').onclick=()=>{if(run.state==='lab'&&!dialogType){run.lab.returnAll();syncLab()}};$('craft').onclick=requestCraft;$('nextWave').onclick=()=>{if(dialogType)return;const hp=run.hp;if(run.nextWave()){clearInput();sync();toast(`${gunName()} Lv.${run.lab.gun.level} · 新一关开始 · 生命补给 +${run.hp-hp}`);$('arena').focus({preventScroll:true})}};$('ignition').onchange=()=>{if(run.state==='lab'&&!dialogType){run.lab.ignition=$('ignition').checked;syncLab()}};$('pause').onclick=pause;$('openLog').onclick=openLog;$('sound').onclick=()=>{sound=!sound;$('soundOff').classList.toggle('hidden',sound);$('sound').setAttribute('aria-label',sound?'关闭音效':'开启音效');beep(440,.1)};
function dragStart(e,selector,from){const b=e.target.closest(selector);if(!b||run.state!=='lab'||dialogType){e.preventDefault();return}const id=b.dataset.add||b.dataset.remove;e.dataTransfer.setData('application/x-valence',JSON.stringify({id,from}));e.dataTransfer.effectAllowed='move'}
$('materialCards').addEventListener('dragstart',e=>dragStart(e,'[data-add]','inventory'));$('furnaceContents').addEventListener('dragstart',e=>dragStart(e,'[data-remove]','furnace'));
for(const [id,to,expected]of [['furnace','furnace','inventory'],['backpack','inventory','furnace']]){const area=$(id);area.addEventListener('dragover',e=>{if(run.state==='lab'&&!dialogType){e.preventDefault();area.classList.add('drag-over')}});area.addEventListener('dragleave',()=>area.classList.remove('drag-over'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('drag-over');try{const data=JSON.parse(e.dataTransfer.getData('application/x-valence'));if(data.from===expected)move(data.id,to)}catch{}})}
$('dialogOverlay').addEventListener('click',e=>{if(e.target===$('dialogOverlay'))closeDialog()});
function moveJoy(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy),s=n>30?30/n:1;joy={x:dx*s/30,y:dy*s/30};$('stick').style.transform=`translate(${dx*s}px,${dy*s}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(run.state!=='playing'||pointer!==null)return;e.preventDefault();pointer=e.pointerId;$('joystick').setPointerCapture(pointer);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveJoy(e)});for(const n of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(n,e=>{if(e.pointerId===pointer)clearInput()});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(dialogType){if(key==='escape'){e.preventDefault();closeDialog()}if(key==='tab'){const items=[...$('dialogCard').querySelectorAll('button')];if(items.length){let at=items.indexOf(document.activeElement),next=(at+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[next].focus()}}return}if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)&&run.state==='playing')e.preventDefault();if(e.repeat)return;if(run.state==='menu'&&/^[1-6]$/.test(key)){e.preventDefault();run.selectStartingGun(gunIds[Number(key)-1]);phase='';sync();return}if(run.state==='lab'&&['arrowleft','arrowright'].includes(key)&&!['SELECT','INPUT','TEXTAREA'].includes(e.target?.tagName)){e.preventDefault();browseRecipe(key==='arrowleft'?-1:1);return}if(run.state==='reward'&&['1','2','3'].includes(key)){e.preventDefault();selectReward(run.rewardChoices[Number(key)-1]);return}if(run.state==='upgrade'&&['1','2','3'].includes(key)){e.preventDefault();chooseAbility(run.upgradeChoices[Number(key)-1]);return}if(key==='enter'&&run.state==='menu'){e.preventDefault();start();return}if(key==='escape'){pause();return}keys[key]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function autoPause(){clearInput();if(run.state==='playing'){run.state='paused';sync()}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)autoPause()});
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000||0));last=now;run.step(dt,{viewport:$('arena').getBoundingClientRect(),x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y});for(const event of run.events){if(event==='shot')beep(run.lab.gun.type==='water'?240:130,.025,'triangle',.008);if(event==='pickup')beep(750,.035,'sine',.01);if(event==='diamond')beep(1000,.025,'sine',.008);if(event==='level')beep(900,.15);if(event==='condenserBurst')toast('水包蓄满 · 自动向侧后方喷水！');if(event==='elite')toast('精英出现 · 击败获得配件三选一');if(event==='boss')toast(run.wave===10?'失控实验核心 · 最终战！':'失控反应釜出现 · 注意预警与绿色缺口');if(event==='bossRing')toast('高压冲击：移向绿色缺口，避开冲击弧');if(event==='bossZone')toast('地面已锁定：离开橙色警戒区');if(event==='overdrive')toast('反应釜过载！出招更快，注意连续冲击');if(event==='hurt'){renderer.shake=10;beep(70,.13,'sawtooth',.025)}}run.events=[];if(run.state!=='lab')renderer.draw(run,now/1000);sync();if(now>toastUntil)$('toast').classList.add('hidden');requestAnimationFrame(frame)}
setSidebarTab('equipment');sync();requestAnimationFrame(frame);
